<template>
  <div class="rp-wrap">
    <!-- 窄屏：半透明遮罩（点遮罩收起面板；弹出后 250ms 内的点击忽略，防双击手势误关） -->
    <transition name="rp-fade">
      <div v-if="narrow && open" class="rp-mask" @click="dismissMask"></div>
    </transition>

    <!-- 窄屏：收起状态下的面板开关 -->
    <button v-if="narrow && !open" class="rp-fab" @click="open = true">☰ 面板</button>

    <aside class="rp-shell" :class="{ 'is-narrow': narrow, 'is-open': narrow && open }">
      <div v-if="narrow" class="rp-handle" aria-hidden="true"><i></i></div>
      <div class="rp-tabs">
        <button :class="{ on: state.tab === 'overall' }" @click="state.tab = 'overall'">整体设置</button>
        <button :class="{ on: state.tab === 'library' }" @click="state.tab = 'library'">部件库</button>
        <button :class="{ on: state.tab === 'props' }" @click="state.tab = 'props'">属性</button>
        <button v-if="narrow" class="rp-close" aria-label="收起面板" @click="open = false">✕</button>
      </div>
      <div class="rp-body">
        <PanelOverall v-show="state.tab === 'overall'" :info="modelInfo" />
        <PanelLibrary v-show="state.tab === 'library'" :sections="catalog.sections" />
        <PanelProps v-show="state.tab === 'props'" :catalog="catalog" />
      </div>
    </aside>
  </div>
</template>

<script>
import { ref, watch, onMounted, onBeforeUnmount } from 'vue'
import { editorState } from '../../lib/editorState'
import { MODEL_INFO } from '../../lib/catalog'
import PanelOverall from './PanelOverall.vue'
import PanelLibrary from './PanelLibrary.vue'
import PanelProps from './PanelProps.vue'

const MOBILE_MQ = '(max-width: 900px)'

export default {
  name: 'RightPanel',
  components: { PanelOverall, PanelLibrary, PanelProps },
  props: {
    catalog: { type: Object, required: true }
  },
  setup() {
    const state = editorState
    const narrow = ref(typeof window !== 'undefined' && !!window.matchMedia && window.matchMedia(MOBILE_MQ).matches)
    const open = ref(!narrow.value)
    let openedAt = 0 // 上次展开时间戳：刚展开的一瞬间不响应遮罩关闭，避免双击手势误关（面板闪现）

    function syncNarrow() {
      const m = typeof window !== 'undefined' && window.matchMedia ? window.matchMedia(MOBILE_MQ) : null
      const now = !!(m && m.matches)
      if (now !== narrow.value) {
        narrow.value = now
        open.value = !now // 窄屏默认收起，宽屏始终展开
      }
    }

    // 窄屏底部抽屉打开时锁定 body 滚动（防滚动穿透），关闭后释放
    function lockBody(lock) {
      if (typeof document === 'undefined') return
      document.body.style.overflow = lock ? 'hidden' : ''
    }

    watch([narrow, open], ([nw, op]) => {
      lockBody(!!nw && !!op)
      editorState.mobileSheetOpen = !!nw && !!op // 同步给 Viewer3D 做模型防遮挡上移
      if (nw && op) openedAt = Date.now()
    })

    // 双击 3D 部件请求 → 窄屏展开操作面板（桌面端本就常驻，无需处理）
    watch(
      () => editorState.panelOpen.nonce,
      () => {
        if (narrow.value) open.value = true
      }
    )

    /** 点击遮罩收起：面板刚展开 250ms 内的点击视为“同一次双击手势的抬起”，忽略（消除闪现） */
    function dismissMask() {
      if (Date.now() - openedAt < 250) return
      open.value = false
    }

    function onKey(e) {
      if (narrow.value && open.value && e.key === 'Escape') open.value = false
    }

    onMounted(() => {
      const m = typeof window !== 'undefined' && window.matchMedia ? window.matchMedia(MOBILE_MQ) : null
      if (m) {
        if (m.addEventListener) m.addEventListener('change', syncNarrow)
        else if (m.addListener) m.addListener(syncNarrow)
      }
      syncNarrow()
      window.addEventListener('keydown', onKey)
    })

    onBeforeUnmount(() => {
      const m = typeof window !== 'undefined' && window.matchMedia ? window.matchMedia(MOBILE_MQ) : null
      if (m) {
        if (m.removeEventListener) m.removeEventListener('change', syncNarrow)
        else if (m.removeListener) m.removeListener(syncNarrow)
      }
      window.removeEventListener('keydown', onKey)
      lockBody(false)
    })

    return { state, modelInfo: MODEL_INFO, narrow, open, dismissMask }
  }
}
</script>

